return {["fb11_01"]={["dsc"]=[[汉水北岸也是相当热闹，自北岸渡口往北，一条笔直的官道直通南阳。此地民风淳朴，路旁夹柳成阴，酒厮林立，且都有一面大大的「酒」旗迎风飘扬，蔚为壮观。也有不少小贩沿路叫买，语多难辨，却也令人盛情难却。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb11_01]],["item1"]=[[fb11item12]],["item2"]=[[fb11item103]],["name"]=[[汉水北岸]],["permission"]=2,["role1"]=[[fb11r01_1]],["role2"]=[[fb11r01_100]],["role3"]=[[fb11r01_101]],["stepMusic"]=[[jiaobu]],["up"]=[[fb11_02]]},["fb11_02"]={["down"]=[[fb11_01]],["dsc"]=[[这里是南阳南门。南阳处南阳盆地内，水土肥沃，物产丰饶。再往南就是汉水了，偶尔有渔夫在河上张网捕鱼。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb11_02]],["name"]=[[南城门]],["permission"]=2,["role1"]=[[fb11r02_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb11_04]]},["fb11_03"]={["dsc"]=[[一间不大的店铺，进门就是一个黄柏木未涂漆的柜台，虽然擦拭得很干净，但是显见是多年之物了，木质都已作深黄。上面一把算盘，一个茶吊。柜台一侧陈列着些杂饰，玉板，银环，珠簪，折扇，应有尽有。墙上挂着几幅字画。]],["id"]=[[fb11_03]],["name"]=[[商号]],["permission"]=2,["right"]=[[fb11_04]],["role1"]=[[fb11r03_1d]],["stepMusic"]=[[jiaobu]]},["fb11_04"]={["down"]=[[fb11_02]],["dsc"]=[[南阳城自古便是关、洛通荆、襄的必经之路。城虽不大，却很是整洁，且民风淳朴。大街上人喊马嘶，尽是南来北往的行商。街西边是一家商号。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb11_04]],["item1"]=[[fb11item10]],["left"]=[[fb11_03]],["name"]=[[南大街]],["permission"]=2,["role1"]=[[ever04_1]],["role2"]=[[2019qxcdg1a]],["role3"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]],["up"]=[[fb11_06]]},["fb11_05"]={["dsc"]=[[方圆数百里内提起迎宾楼可以说是无人不知，无人不晓。当年苏学士云游到此，对迎宾楼的素齐赞不绝口，欣然为其题匾，流下一段传遍海内的佳话，从此迎宾楼名声大震。楼下布置简易，顾客多是匆匆的行人，买点包子，鸡腿、米酒就赶路去了。楼上是雅座。]],["id"]=[[fb11_05]],["name"]=[[迎宾楼]],["permission"]=2,["right"]=[[fb11_06]],["role1"]=[[fb11r05_1]],["role2"]=[[fb11r05_2]],["role3"]=[[QX2r05_1]],["role4"]=[[QX2r05_2e]],["stepMusic"]=[[jiaobu]],["up"]=[[fb11_08]]},["fb11_06"]={["down"]=[[fb11_04]],["dsc"]=[[这里便是当年诸葛先生的故居。南阳城虽不大，因为地出要冲，南来北往的客人特别多，所以也五脏俱全，酒楼，客栈，马店，满城子都是。本地人口甚少，到处都是行色匆匆的江湖客人。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb11_06]],["item1"]=[[bfitem3]],["item2"]=[[dhpd]],["left"]=[[fb11_05]],["name"]=[[南阳城]],["permission"]=2,["right"]=[[fb11_07]],["role1"]=[[fb11r06_1]],["role2"]=[[fb11r06_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb11_09]]},["fb11_07"]={["dsc"]=[[这是一家远近闻名的悦来客栈，生意非常兴隆。外地游客多选择在这里落脚，你可以在这里打听到各地的风土人情。店小二里里外外忙得团团转，接待着南腔北调的客人。]],["id"]=[[fb11_07]],["left"]=[[fb11_06]],["name"]=[[悦来客栈]],["permission"]=2,["role1"]=[[fb11r07_1]],["role2"]=[[fb11r07_100]],["role3"]=[[fb11r07_101]],["roomBgm"]=[[chalou]],["roomBgmRule"]=1,["spaceTime"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb11_10]]},["fb11_08"]={["down"]=[[fb11_05]],["dsc"]=[[这里是雅座，文人学士经常在这里吟诗作画，富商土豪也在这里边吃喝边作交易。这里也是城里举办喜宴的最佳场所。你站在楼上眺望，只觉得心旷神怡。东面是一池湖水，碧波荡漾。北面是崇山峻岭。]],["id"]=[[fb11_08]],["item1"]=[[fb11item7]],["name"]=[[迎宾楼二楼]],["permission"]=2,["role1"]=[[fb11r08_1]],["roomBgm"]=[[chalou]],["roomBgmRule"]=1,["spaceTime"]=2,["stepMusic"]=[[jiaobu]]},["fb11_09"]={["down"]=[[fb11_06]],["dsc"]=[[南阳城自古便是关、洛通荆、襄的必经之路。城虽不大，却很是整洁，且民风淳朴。街西有一家小小的店铺，卖些酒水，肉食给过往的行人。东北面是一个大庙。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb11_09]],["name"]=[[北大街]],["permission"]=2,["rightUp"]=[[fb11_12]],["stepMusic"]=[[jiaobu]],["up"]=[[fb11_11]]},["fb11_10"]={["down"]=[[fb11_07]],["dsc"]=[[这是一间很大的客房，陈设十分简陋。靠墙放了十几张小木床，不少客人正和衣而卧，满屋子都是呼呼的打酣声。西边有张床是空的，你蹑手蹑脚地走了过去。]],["id"]=[[fb11_10]],["item1"]=[[bfitem2]],["name"]=[[客店二楼]],["permission"]=2,["role1"]=[[fb11r10_1]],["stepMusic"]=[[jiaobu]]},["fb11_100"]={["dsc"]=[[这是一条由青石砖铺成的小路，墙壁上每隔十余步就有一盏油灯，能让你看清周围。]],["id"]=[[fb11_100]],["left"]=[[fb11_99]],["name"]=[[密道]],["right"]=[[fb11_101]],["stepMusic"]=[[jiaobu]]},["fb11_101"]={["dsc"]=[[这是一条由青石砖铺成的小路，墙壁上每隔十余步就有一盏油灯，能让你看清周围。]],["id"]=[[fb11_101]],["item1"]=[[fb11item16]],["left"]=[[fb11_100]],["name"]=[[密道]],["permission"]=9,["rightDown"]=[[fb11_108]],["rightUp"]=[[fb11_102]],["role1"]=[[fb11r101_1]],["stepMusic"]=[[jiaobu]]},["fb11_102"]={["dsc"]=[[这是一条由青石砖铺成的小路，墙壁上每隔十余步就有一盏油灯，能让你看清周围。]],["id"]=[[fb11_102]],["leftDown"]=[[fb11_101]],["name"]=[[密道]],["right"]=[[fb11_103]],["stepMusic"]=[[jiaobu]]},["fb11_103"]={["dsc"]=[[这是一条由青石砖铺成的小路，墙壁上每隔十余步就有一盏油灯，能让你看清周围。]],["id"]=[[fb11_103]],["left"]=[[fb11_102]],["name"]=[[密道]],["right"]=[[fb11_104]],["stepMusic"]=[[jiaobu]]},["fb11_104"]={["dsc"]=[[这是一条由青石砖铺成的小路，墙壁