138]],["name"]=[[江边小路]],["permission"]=1,["right"]=[[fb11_137]],["role1"]=[[znq3chfc1]],["role2"]=[[znq3chfc2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb11_139]]},["fb11_139"]={["down"]=[[fb11_138]],["dsc"]=[[一条江边的小路，颇为不平，两边耸立着一些怪石。]],["fightBackground"]=[[森林内]],["id"]=[[fb11_139]],["item1"]=[[2020qmjs1]],["name"]=[[江边小路]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb11_140]]},["fb11_14"]={["down"]=[[fb11_12]],["dsc"]=[[正殿面阔三间，青石为墙，黑瓦覆顶，显出一派简朴的风格，殿内正中供着一尊诸葛武侯彩像，手握羽扇，微捻胡须，神态端然自如；两侧墙壁上题着不少诗篇词赋，大都笔法刚劲，挥毫洒脱，显然是出自一些胸怀大志的壮男儿之手。]],["id"]=[[fb11_14]],["item1"]=[[fb11item2]],["item2"]=[[fb11item3]],["name"]=[[正殿]],["permission"]=2,["role1"]=[[fb11r14_1]],["role2"]=[[fb11r14_100]],["stepMusic"]=[[jiaobu]]},["fb11_140"]={["down"]=[[fb11_139]],["dsc"]=[[一条江边的小路，颇为不平，两边耸立着一些怪石。]],["fightBackground"]=[[森林内]],["id"]=[[fb11_140]],["name"]=[[江边小路]],["permission"]=1,["role1"]=[[fb11r140_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb11_18]]},["fb11_15"]={["down"]=[[fb11_13]],["dsc"]=[[你走在一条尘土飞扬的大驿道上。四周人来人往。挑担子的行商，赶着大车的马夫，上京赶考的书生，熙熙攘攘，非常热闹。不时还有两三骑快马从身边飞驰而过，扬起一路尘埃。道路两旁是整整齐齐的杨树林。附近离汝州城不远，可以看到远处的城墙。]],["id"]=[[fb11_15]],["item1"]=[[fb11item14]],["item2"]=[[bfitem1]],["name"]=[[汝州城]],["permission"]=2,["role1"]=[[fb11r15_1]],["stepMusic"]=[[jiaobu]]},["fb11_17"]={["down"]=[[fb11_18]],["dsc"]=[[面前是一条波涛翻滚的大江。浊流滚滚，万舟竞发。两岸渡船来来往往，江边一长溜摆满了鱼摊，渔家就将船泊在岸边，几个破箩筐支一块木板，板上摆满了活蹦乱跳的汉江鲤鱼。过去不远，是有名的老河口，不少过江客都在这里等待渡船摆渡。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb11_17]],["item1"]=[[fb11item11]],["item2"]=[[fb11item14]],["name"]=[[汉水南岸]],["permission"]=2,["role1"]=[[fb11r17_1]],["stepMusic"]=[[jiaobu]]},["fb11_18"]={["down"]=[[fb11_140]],["dsc"]=[[你走在一条尘土飞扬的大驿道上。四周人来人往。不时还有两三骑快马从身边飞驰而过，扬起一路尘埃。马上的人个个身着劲装，衣甲鲜明，有的还随身佩带着刀剑，看来都是些习武的江湖人。道路两旁是整整齐齐的杨树林。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb11_18]],["item1"]=[[fb11item14]],["name"]=[[大驿道]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb11_17]]},["fb11_19"]={["dsc"]=[[这是一条蜿蜒山道，一直通向山上，上面还是山道。]],["fightBackground"]=[[山内]],["id"]=[[fb11_19]],["item1"]=[[fb11item48]],